use lis::lis_length;

#[test]
fn test_mixed() {
    // LIS: [2, 3, 7, 101] or [2, 5, 7, 101] — length 4
    assert_eq!(lis_length(&[10, 9, 2, 5, 3, 7, 101, 18]), 4);
}

#[test]
fn test_all_increasing() {
    assert_eq!(lis_length(&[1, 2, 3, 4, 5]), 5);
}

#[test]
fn test_all_decreasing() {
    assert_eq!(lis_length(&[5, 4, 3, 2, 1]), 1);
}

#[test]
fn test_single() {
    assert_eq!(lis_length(&[42]), 1);
}

#[test]
fn test_with_duplicates() {
    // [1,3,6,7,9,10] — length 6
    assert_eq!(lis_length(&[1, 3, 6, 7, 9, 4, 10, 5, 6]), 6);
}
